import React, { useState } from "react";
import { BrowserRouter as Router, Route, Routes, Link, Navigate } from "react-router-dom";
import "./styles.css";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";

// OTP Form Schema
const FormSchema = z.object({
  pin: z.string().min(6, {
    message: "Your one-time password must be 6 characters.",
  }),
});

// OTP Form Component
const InputOTPForm = ({ onVerify }) => {
  const form = useForm({
    resolver: zodResolver(FormSchema),
    defaultValues: {
      pin: "",
    },
  });

  const onSubmit = (data) => {
    onVerify(data.pin);
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="otp-form">
        <FormField
          control={form.control}
          name="pin"
          render={({ field }) => (
            <FormItem>
              <FormLabel>One-Time Password</FormLabel>
              <FormControl>
                <InputOTP maxLength={6} {...field}>
                  <InputOTPGroup>
                    {[...Array(6)].map((_, index) => (
                      <InputOTPSlot key={index} index={index} />
                    ))}
                  </InputOTPGroup>
                </InputOTP>
              </FormControl>
              <FormDescription>
                Please enter the one-time password sent to your email.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />
        <button type="submit" className="button">
          Verify OTP
        </button>
      </form>
    </Form>
  );
};

// Home Page Component
const HomePage = () => {
  return (
    <div className="homePage">
      <h1 className="heading">Welcome to Binance Clone</h1>
      <Link to="/login">
        <button className="button">Get Started</button>
      </Link>
      <p className="linkText">
        <Link to="/admin-login" className="link">
          Admin Login
        </Link>
      </p>
    </div>
  );
};

// Login Page Component
const Login = ({ onLogin }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [otpSent, setOtpSent] = useState(false);

  const handleLogin = () => {
    if (!email || !password) {
      setError("Please fill in all fields.");
      return;
    }

    // Simulate OTP generation during login if 2FA is enabled
    setOtpSent(true);
  };

  const handleOTPVerification = (otp) => {
    // Simulate OTP verification
    if (otp === "123456") {
      onLogin();
    } else {
      setError("Invalid OTP. Please try again.");
    }
  };

  return (
    <div className="form-box">
      <h2 className="heading">Login</h2>
      {otpSent ? (
        <>
          <p className="login-subtext">Enter the OTP sent to your email.</p>
          <InputOTPForm onVerify={handleOTPVerification} />
        </>
      ) : (
        <>
          <p className="login-subtext">Enter your email below to login to your account.</p>
          <div className="input-group">
            <label htmlFor="email" className="input-label">Email</label>
            <input
              type="email"
              id="email"
              placeholder="m@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="input"
            />
          </div>
          <div className="input-group">
            <label htmlFor="password" className="input-label">Password</label>
            <input
              type="password"
              id="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="input"
            />
          </div>
          <button onClick={handleLogin} className="button">
            Login
          </button>
        </>
      )}
      {error && <div className="error">{error}</div>}
      <p className="linkText">
        <Link to="/forgot-password" className="link">
          Forgot your password?
        </Link>
      </p>
      <p className="linkText">
        Don't have an account?{" "}
        <Link to="/signup" className="link">
          Sign up
        </Link>
      </p>
    </div>
  );
};

// Signup Page Component
const SignupPage = ({ onSignup }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");
  const [error, setError] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [otpVerified, setOtpVerified] = useState(false);

  const handleSendOTP = () => {
    if (!email || !password || !phone) {
      setError("Please fill in all fields.");
      return;
    }

    const phoneRegex = /^\+92\d{9}$/;
    if (!phoneRegex.test(phone)) {
      setError("Invalid phone number. Please use the format +92XXXXXXXXX.");
      return;
    }

    // Simulate OTP sending (frontend-only)
    setOtpSent(true);
    setError("");
  };

  const handleSignup = () => {
    if (!otpVerified) {
      setError("Please verify OTP first.");
      return;
    }

    onSignup({ email, password, phone });
  };

  return (
    <div className="form-box">
      <h2 className="heading">Sign Up</h2>
      {error && <div className="error">{error}</div>}

      {/* Email Field */}
      <div className="input-group">
        <label htmlFor="email" className="input-label">Email</label>
        <input
          type="email"
          id="email"
          placeholder="m@example.com"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="input"
        />
      </div>

      {/* Password Field */}
      <div className="input-group">
        <label htmlFor="password" className="input-label">Password</label>
        <input
          type="password"
          id="password"
          placeholder="Password (min 8 characters)"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="input"
        />
      </div>

      {/* Phone Field */}
      <div className="input-group">
        <label htmlFor="phone" className="input-label">Phone Number</label>
        <input
          type="text"
          id="phone"
          placeholder="+92XXXXXXXXX"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          className="input"
        />
      </div>

      {/* OTP Section */}
      {!otpSent ? (
        <button onClick={handleSendOTP} className="button">
          Send OTP
        </button>
      ) : (
        <>
          <InputOTPForm onVerify={() => setOtpVerified(true)} />
          <button onClick={handleSignup} className="button">
            Sign Up
          </button>
        </>
      )}

      {/* Login Link */}
      <p className="linkText">
        Already have an account?{" "}
        <Link to="/login" className="link">
          Login
        </Link>
      </p>
    </div>
  );
};

// Settings Page Component
const Settings = ({ user, onEnable2FA }) => {
  const [is2FAEnabled, setIs2FAEnabled] = useState(user?.is2FAEnabled || false);

  const handleToggle2FA = () => {
    setIs2FAEnabled(!is2FAEnabled);
    onEnable2FA(!is2FAEnabled);
  };

  return (
    <div className="form-box">
      <h2 className="heading">Settings</h2>
      <div className="input-group">
        <label htmlFor="2fa" className="input-label">Enable Two-Factor Authentication (2FA)</label>
        <input
          type="checkbox"
          id="2fa"
          checked={is2FAEnabled}
          onChange={handleToggle2FA}
          className="input"
        />
      </div>
    </div>
  );
};

// Forgot Password Page Component
const ForgotPassword = () => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [otpSent, setOtpSent] = useState(false);

  const handleSendOTP = () => {
    if (!email) {
      setError("Please enter your email.");
      return;
    }

    // Simulate OTP generation for password reset
    setOtpSent(true);
  };

  const handleOTPVerification = (otp) => {
    // Simulate OTP verification
    if (otp === "123456") {
      // Redirect to password reset page
      window.location.href = "/reset-password";
    } else {
      setError("Invalid OTP. Please try again.");
    }
  };

  return (
    <div className="form-box">
      <h1 className="heading">Forgot Password</h1>
      {otpSent ? (
        <>
          <p className="forgot-password-subtext">Enter the OTP sent to your email.</p>
          <InputOTPForm onVerify={handleOTPVerification} />
        </>
      ) : (
        <>
          <p className="forgot-password-subtext">
            Enter your email below to receive a password reset link.
          </p>
          <div className="input-group">
            <label htmlFor="email" className="input-label">Email</label>
            <input
              type="email"
              id="email"
              placeholder="m@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="input"
            />
          </div>
          <button onClick={handleSendOTP} className="button">
            Send OTP
          </button>
        </>
      )}
      {error && <div className="error">{error}</div>}
      <p className="linkText">
        Remembered your password?{" "}
        <Link to="/login" className="link">
          Go back to login
        </Link>
      </p>
    </div>
  );
};

// Reset Password Page Component
const ResetPassword = () => {
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");

  const handleResetPassword = () => {
    if (!password || !confirmPassword) {
      setError("Please fill in all fields.");
      return;
    }

    if (password !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }

    // Simulate password reset
    window.location.href = "/login";
  };

  return (
    <div className="form-box">
      <h1 className="heading">Reset Password</h1>
      <div className="input-group">
        <label htmlFor="password" className="input-label">New Password</label>
        <input
          type="password"
          id="password"
          placeholder="Enter new password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="input"
        />
      </div>
      <div className="input-group">
        <label htmlFor="confirmPassword" className="input-label">Confirm Password</label>
        <input
          type="password"
          id="confirmPassword"
          placeholder="Confirm new password"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          className="input"
        />
      </div>
      <button onClick={handleResetPassword} className="button">
        Reset Password
      </button>
      {error && <div className="error">{error}</div>}
    </div>
  );
};

// App Component
const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);

  const handleLogin = () => {
    setIsLoggedIn(true);
    setUser({ email: "user@example.com", is2FAEnabled: false });
  };

  const handleSignup = (userData) => {
    console.log("User signed up:", userData);
    setUser(userData);
    setIsLoggedIn(true);
  };

  const handleEnable2FA = (isEnabled) => {
    setUser((prevUser) => ({ ...prevUser, is2FAEnabled: isEnabled }));
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route
            path="/login"
            element={
              isLoggedIn ? (
                <Navigate to="/dashboard" />
              ) : (
                <Login onLogin={handleLogin} />
              )
            }
          />
          <Route
            path="/signup"
            element={<SignupPage onSignup={handleSignup} />}
          />
          <Route
            path="/settings"
            element={
              isLoggedIn ? (
                <Settings user={user} onEnable2FA={handleEnable2FA} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/forgot-password"
            element={<ForgotPassword />}
          />
          <Route
            path="/reset-password"
            element={<ResetPassword />}
          />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
